CREATE TABLE r1 AS SELECT * FROM t1 WHERE EXISTS(SELECT 1 FROM t2 WHERE c=a AND b IS a); CREATE TABLE r2 AS SELECT * FROM t1 WHERE EXISTS(SELECT 1 FROM t2 WHERE a=c AND a IS b); CREATE TABLE r3 AS SELECT * FROM t1 WHERE EXISTS(SELECT 1 FROM t2 WHERE a=c AND b IS a); CREATE TABLE r4 AS SELECT * FROM t1 WHERE EXISTS(SELECT 1 FROM t2 WHERE c=a AND a IS b);